"""The source files `rustc` read to build the production targets, from the dep-info it wrote.

The compiler, not a parser of ours, knows which files are part of a build: a file named by `mod`, by
`#[path]` (also under `cfg_attr`), by `include!` or `include_str!`, the build script a manifest names.
`cargo check --message-format=json` reports every unit it builds or finds fresh, and next to each
unit's output is a `.d` file that lists each file the compiler opened. This module maps the first to
the second and reads the second. Nothing here knows what Rust looks like; whatever cannot be read
is an error, never a smaller list.
"""

import json
import os
import re
from pathlib import Path


class DepInfoError(Exception):
    pass


def units(lines, root, tests=False):
    """The units of the crates in `root` that `cargo check --message-format=json` built or found fresh.

    Returns (kinds, source path, output files) of each. A unit of a test profile is refused unless
    `tests` says the run is the one of the tests.
    """
    root = Path(root).resolve()
    found = []
    for number, line in enumerate(lines, 1):
        line = line.strip()
        if not line.startswith("{"):
            continue
        try:
            message = json.loads(line)
        except ValueError as err:
            raise DepInfoError(f"line {number} of the cargo output is not JSON: {err}") from err
        if message.get("reason") != "compiler-artifact":
            continue
        src = Path(message["target"]["src_path"])
        try:
            relative = src.resolve().relative_to(root)
        except ValueError:
            continue  # a dependency from a registry or a git checkout
        if relative.parts[0] == "target":
            continue  # generated by a build, not a file of the repository
        if message.get("profile", {}).get("test") and not tests:
            raise DepInfoError(f"{src} was built as a test unit: only production targets may be listed")
        found.append((tuple(message["target"]["kind"]), src, [Path(f) for f in message["filenames"]]))
    return found


def dep_info_path(output, kinds=()):
    """The `.d` file of one output of a unit: `libx-HASH.rmeta` and `x-HASH` both name `x-HASH.d`.

    The output of a build script is `build-script-NAME` with no hash, in a directory of its own
    that holds one `build_script_NAME-HASH.d`.
    """
    if "custom-build" in kinds:
        found = sorted(output.parent.glob("*.d"))
        if len(found) == 1:
            return found[0]
        raise DepInfoError(f"{len(found)} dep-info files next to the build script {output}, and one was expected")
    stem = output.name.split(".", 1)[0]
    candidates = [stem]
    if stem.startswith("lib"):
        candidates.append(stem[3:])
    for name in candidates:
        path = output.with_name(name + ".d")
        if path.is_file():
            return path
    raise DepInfoError(f"no dep-info next to {output}")


def _split_unescaped(text):
    parts, current, i = [], [], 0
    while i < len(text):
        char = text[i]
        if char == "\\" and i + 1 < len(text) and text[i + 1] in " \\":
            current.append(text[i + 1])
            i += 2
            continue
        if char == " ":
            if current:
                parts.append("".join(current))
                current = []
        else:
            current.append(char)
        i += 1
    if current:
        parts.append("".join(current))
    return parts


def read(path):
    """The files a `.d` lists as what its outputs depend on, as written."""
    deps = []
    text = Path(path).read_text(encoding="utf-8", errors="surrogateescape")
    for line in text.splitlines():
        if not line.strip() or line.startswith("#"):
            continue
        match = re.search(r"(?<!\\):(?: |$)", line)
        if not match:
            raise DepInfoError(f"{path}: a line that is neither a rule nor a comment: {line[:60]!r}")
        deps.extend(_split_unescaped(line[match.end():]))
    return deps


def production_files(lines, root, tests=False):
    """The repository files, relative to `root`, that the units of a run read; an error if there are none.

    With `tests` the run is `cargo check --tests` and its test units are accepted; without it a test unit
    is an error, so a production list can never hold a file only the tests read.
    """
    root = Path(root).resolve()
    files, roots = set(), []
    for kinds, src, outputs in units(lines, root, tests):
        roots.append(src.resolve().relative_to(root).as_posix())
        for output in outputs:
            for dep in read(dep_info_path(output, kinds)):
                path = Path(dep) if os.path.isabs(dep) else root / dep
                try:
                    rel = path.resolve().relative_to(root)
                except ValueError:
                    continue
                if rel.parts and rel.parts[0] != "target":
                    files.add(rel.as_posix())
    if not roots:
        raise DepInfoError("cargo reported no unit of this crate: nothing was checked")
    for src in roots:
        if src not in files:
            raise DepInfoError(f"the dep-info of {src} does not list {src} itself: it was not read as it should")
    if not files:
        raise DepInfoError("the dep-info is empty")
    return files
